package com.andye.warmod.block;import com.andye.warmod.block.entity.*;import com.andye.warmod.radar.station.network.RadarStationNetworking;import com.mojang.serialization.MapCodec;import java.util.function.BiConsumer;import net.minecraft.core.*;import net.minecraft.network.chat.Component;import net.minecraft.server.level.ServerLevel;import net.minecraft.world.*;import net.minecraft.world.entity.player.Player;import net.minecraft.world.item.ItemStack;import net.minecraft.world.level.*;import net.minecraft.world.level.block.*;import net.minecraft.world.level.block.entity.*;import net.minecraft.world.level.block.state.*;import net.minecraft.world.level.block.state.properties.*;import net.minecraft.world.phys.BlockHitResult;import net.minecraft.world.phys.shapes.*;import org.jspecify.annotations.Nullable;public final class RadarStationBlock extends BaseEntityBlock {public static final MapCodec<RadarStationBlock>CODEC=simpleCodec(RadarStationBlock::new);public static final EnumProperty<RadarStationPart>PART=EnumProperty.create("part",RadarStationPart.class);public static final Property<Direction>FACING=HorizontalDirectionalBlock.FACING;private static final VoxelShape MAST=Block.box(5,0,5,11,16,11),SUPPORT=Block.box(3,0,3,13,10,13);public RadarStationBlock(BlockBehaviour.Properties p){super(p);registerDefaultState(stateDefinition.any().setValue(PART,RadarStationPart.BOTTOM_CENTER).setValue(FACING,Direction.NORTH));}@Override protected MapCodec<?extends RadarStationBlock>codec(){return CODEC;}@Override protected void createBlockStateDefinition(StateDefinition.Builder<Block,BlockState>b){b.add(PART,FACING);}@Override public @Nullable BlockEntity newBlockEntity(BlockPos pos,BlockState state){return state.getValue(PART).centre()?new RadarStationBlockEntity(pos,state):null;}public static @Nullable RadarStationBlockEntity resolve(BlockGetter level,BlockPos pos,BlockState state){if(!state.is(ModBlocks.RADAR_STATION))return null;BlockPos c=state.getValue(PART).resolveCentre(pos,state.getValue(FACING));return level.getBlockEntity(c)instanceof RadarStationBlockEntity r?r:null;}@Override protected VoxelShape getShape(BlockState s,BlockGetter l,BlockPos p,CollisionContext c){RadarStationPart part=s.getValue(PART);return part.layer()==0?Shapes.block():part==RadarStationPart.MIDDLE_CENTER?MAST:part.layer()==1&&part.corner()?SUPPORT:Shapes.empty();}@Override protected InteractionResult useWithoutItem(BlockState s,Level l,BlockPos p,Player player,BlockHitResult hit){if(l.isClientSide())return InteractionResult.SUCCESS;RadarStationBlockEntity r=resolve(l,p,s);if(r==null)return InteractionResult.FAIL;if(player.isShiftKeyDown())player.sendSystemMessage(Component.literal("Radar "+r.radarId().toString().substring(0,8)+" | Warning "+(int)r.warningRadius()+" | "+(r.warningActive()?"ACTIVE":"CLEAR")));else RadarStationNetworking.open((net.minecraft.server.level.ServerPlayer)player,r);return InteractionResult.SUCCESS_SERVER;}@Override protected boolean isSignalSource(BlockState s){return true;}@Override protected int getSignal(BlockState s,BlockGetter l,BlockPos p,Direction d){RadarStationBlockEntity r=resolve(l,p,s);return r!=null&&r.warningActive()?15:0;}@Override protected int getDirectSignal(BlockState s,BlockGetter l,BlockPos p,Direction d){return getSignal(s,l,p,d);}@Override public BlockState playerWillDestroy(Level l,BlockPos p,BlockState s,Player player){if(l instanceof ServerLevel server)RadarStationStructure.teardown(server,p,s,true);return s;}@Override public void playerDestroy(Level l,Player p,BlockPos pos,BlockState s,@Nullable BlockEntity be,ItemStack tool){}@Override protected void onExplosionHit(BlockState s,ServerLevel l,BlockPos p,Explosion e,BiConsumer<ItemStack,BlockPos> hit){RadarStationStructure.teardown(l,p,s,true);}}